// ❌ PRE-GENERICS (Dangerous)
ArrayList oldList = new ArrayList();
oldList.add("Usman");
oldList.add(100); // Compiles fine, but crashes the program later!

// ✅ MODERN GENERICS (Type-Safe)
// The <String> diamond operator enforces strict data types at compile time.
List<String> secureList = new ArrayList<>();
secureList.add("Usman");
// secureList.add(100); // Compiler ERROR! Safe architecture.

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class ListArchitecture {
    public static void main(String[] args) {
        // ARRAYLIST: Backed by a contiguous array.
        // Great for reading data quickly. Bad for inserting in the middle.
        List<String> arrayList = new ArrayList<>();
        arrayList.add("Data 1");

        // LINKEDLIST: Backed by scattered nodes pointing to each other.
        // Great for inserting/deleting in the middle. Bad for searching.
        List<String> linkedList = new LinkedList<>();
        linkedList.add("Node 1");
    }
}

import java.util.HashSet;
import java.util.TreeSet;
import java.util.Set;

public class SetDemo {
    public static void main(String[] args) {
        // HASHSET: Lightning fast O(1) lookups. Random order.
        Set<String> hashSet = new HashSet<>();
        hashSet.add("Zebra");
        hashSet.add("Apple");
        System.out.println(hashSet); // Output might be: [Zebra, Apple]

        // TREESET: Slower O(log N) lookups. Automatically sorted!
        Set<String> treeSet = new TreeSet<>();
        treeSet.add("Zebra");
        treeSet.add("Apple");
        System.out.println(treeSet); // Output ALWAYS: [Apple, Zebra]
    }
}

import java.util.HashMap;
import java.util.Map;

public class MapDemo {
    public static void main(String[] args) {
        // Map<KeyType, ValueType>
        Map<Integer, String> students = new HashMap<>();

        // 1. ADDING DATA (.put)
        students.put(101, "Usman");
        students.put(102, "Ali");

        // Overwriting data: Re-using a Key replaces the old Value
        students.put(102, "Ahmed"); 

        // 2. INSTANT RETRIEVAL (.get)
        String target = students.get(101); // Instantly returns "Usman"

        // 3. CHECKING EXISTENCE
        boolean hasKey = students.containsKey(999); // false
    }
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class IteratorDemo {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>();
        names.add("Usman");
        names.add("Bug");

        // THE SECURE WAY TO LOOP AND DELETE
        Iterator<String> cursor = names.iterator();

        while (cursor.hasNext()) {
            String current = cursor.next();
            if (current.equals("Bug")) {
                cursor.remove(); // Safely deletes the item from the list
            }
        }
    }
}
